                 const dataInterpolator = d3.interpolate({x: d.source_x, y: d.source_y}, {x: d.target_x, y: d.target_y});
                 const transformInterpolator = d3.interpolate({x: source_transform_x, y: source_transform_y}, {x: target_transform_x, y: target_transform_y});
